# THIS IS A REFERENCE SCRIPT GENERATED BY GPT-5.3 THROUGH THE CHATGPT WEB INTERFACE.
# JUST TO SEE WHAT KIND OF A DIFFERENCE SHEER MODEL SIZE AND PERFORMANCE MAKES.

# --> Looks like the SNR is still wrong, or at least way too high (averaging several hundred, tutorial maxed out at ~19)

import os
import numpy as np
import matplotlib.pyplot as plt

from gwpy.timeseries import TimeSeries
from gwosc.datasets import event_gps

from pycbc.types import TimeSeries as PyCBCTimeSeries
from pycbc.waveform import get_td_waveform
from pycbc.filter import matched_filter
from pycbc.psd import welch, interpolate, inverse_spectrum_truncation

# -------------------------------
# Config
# -------------------------------
EVENT = "GW150914"
PARENT_DIR = os.path.abspath(os.path.join(os.getcwd(), ".."))

H1_FILE = os.path.join(PARENT_DIR, "gwosc_gw150914_h1.hdf5")
L1_FILE = os.path.join(PARENT_DIR, "gwosc_gw150914_l1.hdf5")

START_OFFSET = -8
END_OFFSET = 4

# -------------------------------
# Task 1: Data fetching
# -------------------------------
if os.path.exists(H1_FILE) and os.path.exists(L1_FILE):
    print("Loading data from disk...")
    h1 = TimeSeries.read(H1_FILE, format='hdf5')
    l1 = TimeSeries.read(L1_FILE, format='hdf5')
else:
    print("Fetching data from GWOSC...")
    gps = event_gps(EVENT)
    start = gps + START_OFFSET
    end = gps + END_OFFSET

    h1 = TimeSeries.fetch_open_data('H1', start, end)
    l1 = TimeSeries.fetch_open_data('L1', start, end)

    # Save to disk
    h1.write(H1_FILE, format='hdf5')
    l1.write(L1_FILE, format='hdf5')

    # Plot raw strain
    for data, label in [(h1, "H1"), (l1, "L1")]:
        plt.figure()
        plt.plot(data.times.value, data.value)
        plt.xlabel("Time (s)")
        plt.ylabel("Strain")
        plt.title(f"{label} Raw Strain")
        plt.savefig(f"{label}_raw_strain.png")
        plt.close()

# -------------------------------
# Task 2: Filtering
# -------------------------------
h1_white = h1.whiten()
l1_white = l1.whiten()

h1_bp = h1_white.bandpass(30, 250)
l1_bp = l1_white.bandpass(30, 250)

for data, label, tag in [
    (h1_white, "H1", "whitened"),
    (l1_white, "L1", "whitened"),
    (h1_bp, "H1", "bandpassed"),
    (l1_bp, "L1", "bandpassed"),
]:
    plt.figure()
    plt.plot(data.times.value, data.value)
    plt.title(f"{label} {tag}")
    plt.savefig(f"{label}_{tag}.png")
    plt.close()

# -------------------------------
# Task 3: Q-transform
# -------------------------------
# GPT-5.3 screwed up the colormap, but everything else seems fine.
for data, label in [(h1_bp, "H1"), (l1_bp, "L1")]:
    q = data.q_transform()
    plt.figure()
    q.plot(clim=(0, 25))
    plt.title(f"{label} Q-transform")
    plt.savefig(f"{label}_qtransform.png")
    plt.close()

# -------------------------------
# Task 4: Convert to PyCBC
# -------------------------------
def to_pycbc(ts):
    return PyCBCTimeSeries(ts.value, delta_t=ts.dt.value)

h1_pycbc = to_pycbc(h1_bp)
l1_pycbc = to_pycbc(l1_bp)

# Ensure same length
min_len = min(len(h1_pycbc), len(l1_pycbc))
h1_pycbc = h1_pycbc[:min_len]
l1_pycbc = l1_pycbc[:min_len]

# -------------------------------
# Task 5: Template creation
# -------------------------------
masses = [30, 32, 34, 36, 38, 40]
templates = {}

# GPT-5.3 had a different approximant here
for m in masses:
    hp, _ = get_td_waveform(
        approximant="SEOBNRv4_opt",
        mass1=m,
        mass2=m,
        delta_t=h1_pycbc.delta_t,
        f_lower=30
    )

    if hp.duration < 0.2:
        continue

    # Resize to match data
    hp.resize(len(h1_pycbc))

    # Normalize
    hp *= max(h1_pycbc.max(), l1_pycbc.max()) / max(hp)

    templates[m] = hp

    # Save template
    np.save(f"template_{m}Msun.npy", hp.numpy())

    # Plot overlay
    for data, label in [(h1_pycbc, "H1"), (l1_pycbc, "L1")]:
        plt.figure()
        plt.plot(data.sample_times, data, label="Data", alpha=0.7)
        plt.plot(hp.sample_times, hp, label=f"Template {m}Msun", alpha=0.9)
        plt.legend()
        plt.title(f"{label} Template Overlay ({m} Msun)")
        plt.savefig(f"{label}_template_{m}.png")
        plt.close()

# -------------------------------
# Task 6: PSD
# -------------------------------
def compute_psd(data):
    psd = welch(data, seg_len=1024)
    psd = interpolate(psd, data.delta_f)
    psd = inverse_spectrum_truncation(psd, 4 * 1024, low_frequency_cutoff=30)
    return psd

h1_psd = compute_psd(h1_pycbc)
l1_psd = compute_psd(l1_pycbc)

for psd, label in [(h1_psd, "H1"), (l1_psd, "L1")]:
    plt.figure()
    freqs = np.arange(len(psd)) * psd.delta_f
    plt.loglog(freqs, psd)
    plt.title(f"{label} PSD")
    plt.savefig(f"{label}_psd.png")
    plt.close()

# -------------------------------
# Task 7: Matched filtering
# -------------------------------
best = {"H1": (None, 0), "L1": (None, 0)}

for m, temp in templates.items():
    for data, psd, label in [
        (h1_pycbc, h1_psd, "H1"),
        (l1_pycbc, l1_psd, "L1"),
    ]:
        snr = matched_filter(temp, data, psd=psd, low_frequency_cutoff=30)
        snr = snr.crop(4, 4)

        peak = abs(snr).max()

        if peak > best[label][1]:
            best[label] = (m, peak)

        plt.figure()
        plt.plot(snr.sample_times, abs(snr))
        plt.title(f"{label} SNR (Template {m} Msun)")
        plt.savefig(f"{label}_snr_{m}.png")
        plt.close()

# Report best templates
print("\nBest templates:")
for det in best:
    print(f"{det}: {best[det][0]} Msun (SNR={best[det][1]:.2f})")